const input = $('Execute Workflow Trigger').item.json;
const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let p = {};
try { p = JSON.parse(raw); } catch (e) { p = {}; }
const allowed = ['critical', 'high', 'normal', 'low'];
const priority = allowed.includes(p.priority) ? p.priority : 'normal';
const confidence = Math.max(0, Math.min(1, Number(p.confidence) || 0));
return [{ json: {
  ...input,
  priority,
  category: typeof p.category === 'string' ? p.category : 'other',
  confidence,
  sensitive: priority === 'critical' || priority === 'high',
  stages: [...(input.stages || []), { stage: 'Intake', completed: true, confidence }]
}}];
